-- A business page's hours row (BP app business-hours, Jesse 2026-10-25): a green dot "Open till
-- 9 PM", orange "Closes soon", red "Closed till Tue 4 PM". The app already reads places with
-- select=*.
--
-- hours: {"sun": [["12:00","20:00"]], "mon": [], ...}, Sunday to Saturday, each day's ranges in the
-- Town's clock, an empty list closed. A range ending at or before its start runs past midnight.
-- Filled once on 2026-10-25 for the 75 places with a Search logo: Google Maps' regular hours where
-- Google lists the place (Jesse: "its a fact"), else the hours on the place's own website or
-- Facebook. 10 places list no hours anywhere and stay null, which shows no row.

alter table public.places add column if not exists hours jsonb;

